#ifndef _SHELL_SERVICE_H_
#define _SHELL_SERVICE_H_

#include "adb.h"

/****************************************************************************
 * Public types
 ****************************************************************************/

#define ADB_SHELL_PREFIX "shell:"

/****************************************************************************
 * Public Function Prototypes
 ****************************************************************************/

adb_service_t* shell_service(adb_client_t *client, const char *params);

#endif /* _SHELL_SERVICE_H_ */
