/* Direct path via vela_tls */
static int llm_http_direct(const char* post_data, resp_buf_t* rb,
    int* out_status)
{
    /* Snapshot config under lock */
    char api_key[128], llm_host[128], llm_path[128], llm_port[8], model[64];
    pthread_mutex_lock(&s_llm_lock);
    memcpy(api_key, s_api_key, sizeof(api_key));
    memcpy(llm_host, s_llm_host, sizeof(llm_host));
    memcpy(llm_path, s_llm_path, sizeof(llm_path));
    memcpy(llm_port, s_llm_port, sizeof(llm_port));
    memcpy(model, s_model, sizeof(model));
    pthread_mutex_unlock(&s_llm_lock);

    /* Allocate the response buffer once and hand it directly to the
     * TLS layer.  Previously we allocated a separate raw_buf and then
     * copied into resp_buf — doubling peak memory usage.  Now the
     * resp_buf IS the raw buffer, eliminating the copy. */
    size_t raw_cap = AGENT_LLM_STREAM_BUF_SIZE;
    if (resp_buf_init(rb, raw_cap) != OK)
        return ERROR;

    /* OpenAI-compatible format: Authorization: Bearer <key> */
    char auth_header[256];
    snprintf(auth_header, sizeof(auth_header), "Bearer %s", api_key);

    /* Extract provider ID from model string (e.g. "xiaomi/mimo-claw-0301" →
     * "xiaomi") Mify gateway requires X-Model-Provider-Id header for routing. */
    char provider[64] = { 0 };
    const char* slash = strchr(model, '/');
    if (slash) {
        size_t plen = (size_t)(slash - model);
        if (plen >= sizeof(provider))
            plen = sizeof(provider) - 1;
        memcpy(provider, model, plen);
    }

    vela_header_t hdrs[] = { { "Authorization", auth_header },
        { provider[0] ? "X-Model-Provider-Id" : NULL,
            provider[0] ? provider : NULL },
        { NULL, NULL } };

    int status;
    int use_tls = (strcmp(llm_port, "443") == 0);

    if (use_tls) {
        status = vela_https_post_json(llm_host, llm_port, llm_path, hdrs, post_data,
            rb->data, raw_cap);
    } else {
        status = vela_http_post_json(llm_host, llm_port, llm_path, hdrs, post_data,
            rb->data, raw_cap);
    }

    if (status < 0) {
        resp_buf_free(rb);
        return ERROR;
    }

    /* Update length — TLS layer NUL-terminated the buffer */
            if (strcmp(g_router_presets[i].name, arg1) == 0) {
                preset = &g_router_presets[i];
                break;
            }
        }

        if (preset) {
            host = preset->host;
            path = preset->path;
            model = preset->model;
            cost_tier = preset->cost_tier;
            port = "443";
            if (argc >= 3)
                api_key = argv[2];
        } else {
            /* Custom: arg1 is bare host */
            host = arg1;
            port = "443";
            if (argc >= 3)
                model = argv[2];
            if (argc >= 4)
                api_key = argv[3];
        }
    }

    /* Build backend and write to router slot 0 */
    llm_backend_t backend = { 0 };
    strncpy(backend.host, host, sizeof(backend.host) - 1);
    backend.host[sizeof(backend.host) - 1] = '\0';
    strncpy(backend.path, path, sizeof(backend.path) - 1);
    backend.path[sizeof(backend.path) - 1] = '\0';
    strncpy(backend.port, port, sizeof(backend.port) - 1);
    backend.port[sizeof(backend.port) - 1] = '\0';
    if (model) {
        strncpy(backend.model, model, sizeof(backend.model) - 1);
        backend.model[sizeof(backend.model) - 1] = '\0';
    }

    /* Preserve existing API key if not provided */
    if (api_key) {
        strncpy(backend.api_key, api_key, sizeof(backend.api_key) - 1);
        backend.api_key[sizeof(backend.api_key) - 1] = '\0';
    } else {
        llm_backend_t old;
        if (llm_router_get_backend(0, &old) == 0 && old.api_key[0]) {
            strncpy(backend.api_key, old.api_key, sizeof(backend.api_key) - 1);
            backend.api_key[sizeof(backend.api_key) - 1] = '\0';
        }
    }

    backend.priority = 0;
    backend.cost_tier = cost_tier;
    backend.enabled = true;

    /* Write to router slot 0 and apply immediately.
     * llm_router_apply() -> llm_set_all() already persists
     * llm_host/llm_path/llm_port/api_key/model to config_store,
     * so config_show and reboot are covered without extra writes here. */
    llm_router_set_backend(0, &backend);
    llm_router_apply(0);

    printf("LLM backend: %s:%s%s (model: %s) [router slot 0]\n",
        host, port, path, model ? model : "(unchanged)");
    if (api_key) {
        printf("API key saved.\n");
    }
}


